@push('scripts')
<script>
var reviewForm=document.querySelector('[data-review-form]');if(reviewForm){var feedback=reviewForm.querySelector('#feedback');var help=reviewForm.querySelector('[data-feedback-help]');var button=reviewForm.querySelector('[data-submit-button]');function updateFeedback(){var selected=reviewForm.querySelector('input[name="decision"]:checked');var required=selected&&['returned','rejected'].indexOf(selected.value)!==-1;feedback.required=required;help.textContent=required?'(required for this decision)':'(optional for endorsement or approval)';}reviewForm.querySelectorAll('input[name="decision"]').forEach(function(input){input.addEventListener('change',updateFeedback);});reviewForm.addEventListener('submit',function(){button.disabled=true;button.innerHTML='<i class="mdi mdi-loading mdi-spin mr-1"></i>Recording...';});updateFeedback();}
</script>
@endpush
